create table "example"."live__stream_ticket" ("scope_id" uuid not null, "id" uuid not null, "created_at" timestamptz(3) default now() not null, "updated_at" timestamptz(3) default now() not null, "version" bigint default 1 not null, "public_id" text collate "C" not null, "verifier" text not null, "principal" jsonb not null, "principal_resolver" text collate "C" not null, "principal_id" text collate "C" not null, "action" text collate "C", "endpoint" text not null, "expires_at" timestamptz(3) not null, "used_at" timestamptz(3), constraint "live__stream_ticket_endpoint_enum" check ("endpoint" in ('subscribe')), constraint "live__stream_ticket_pkey" primary key ("scope_id", "id"));
create unique index "live__stream_ticket__public_id_uq" on "example"."live__stream_ticket" using btree ("scope_id", "public_id");
create index "live__stream_ticket__expires_at_ix" on "example"."live__stream_ticket" using btree ("scope_id", "expires_at");
alter table "example".live__stream_ticket enable row level security;
alter table "example".live__stream_ticket force row level security;
create policy scoped on "example".live__stream_ticket using (scope_id = coalesce(nullif(current_setting('keelwerk.tenant_id', true), '')::uuid, nullif(current_setting('keelwerk.backend_id', true), '')::uuid, nullif(current_setting('keelwerk.deployment_id', true), '')::uuid)) with check (scope_id = coalesce(nullif(current_setting('keelwerk.tenant_id', true), '')::uuid, nullif(current_setting('keelwerk.backend_id', true), '')::uuid, nullif(current_setting('keelwerk.deployment_id', true), '')::uuid));
create policy maintenance on "example".live__stream_ticket using (current_setting('keelwerk.scope', true) = 'namespace') with check (current_setting('keelwerk.scope', true) = 'namespace');
grant select, insert, update, delete on "example"."live__stream_ticket" to "keelwerk_app"
